// orient(a,b,p) = cross(b-a, p-a).  Positive means p is left of directed edge a->b.
inline double orient(double ax, double ay, double bx, double by,
                     double px, double py) {
    return (bx - ax) * (py - ay) - (by - ay) * (px - ax);
}

// Sutherland-Hodgman clip of a CCW convex subject by a CCW convex clip polygon.
// `clip_poly` is read-only (so a prepared Gi can be reused across candidates).
// `out` / `in` are scratch; on return `out` holds the CCW intersection, or
// fewer than 3 vertices when the intersection is degenerate.
inline void clip_convex_ccw(const std::vector<std::array<double, 2>>& subject,
                            const std::vector<std::array<double, 2>>& clip_poly,
                            std::vector<std::array<double, 2>>& out,
                            std::vector<std::array<double, 2>>& in) {
    const int clip_n = static_cast<int>(clip_poly.size());
    out = subject;
    in.clear();
    for (int e = 0; e < clip_n && out.size() >= 3; ++e) {
        const int e1 = (e + 1 == clip_n) ? 0 : e + 1;
        const double ax = clip_poly[e][0],  ay = clip_poly[e][1];
        const double bx = clip_poly[e1][0], by = clip_poly[e1][1];
        in.swap(out);
        out.clear();
        const int sz = static_cast<int>(in.size());
        int prev = sz - 1;
        for (int i = 0; i < sz; ++i) {
            const auto& cur = in[i];
            const auto& prv = in[prev];
            prev = i;
            // >= 0 means the vertex is on/left of clip edge a->b (inside).
            const double cur_side = orient(ax, ay, bx, by, cur[0], cur[1]);
            const double prv_side = orient(ax, ay, bx, by, prv[0], prv[1]);
            const bool cur_in = cur_side >= 0.0, prv_in = prv_side >= 0.0;
            if (cur_in) {
                if (!prv_in) {
                    const double t = prv_side / (prv_side - cur_side);
                    out.push_back({prv[0] + t * (cur[0] - prv[0]),
                                   prv[1] + t * (cur[1] - prv[1])});
                }
                out.push_back(cur);
            } else if (prv_in) {
                const double t = prv_side / (prv_side - cur_side);
                out.push_back({prv[0] + t * (cur[0] - prv[0]),
                               prv[1] + t * (cur[1] - prv[1])});
            }
        }
    }
}

inline void points_to_xy(const std::vector<Point>& pts,
                         std::vector<std::array<double, 2>>& xy) {
    xy.clear();
    xy.reserve(pts.size());
    for (const auto& p : pts)
        xy.push_back({CGAL::to_double(p.x()), CGAL::to_double(p.y())});
}

// Convert a convex Point polygon to CCW doubles once (e.g. conv(G_i) at the
// start of a stab step) so every candidate can clip against the same buffer.
inline void prepare_convex_xy(const std::vector<Point>& pts,
                              std::vector<std::array<double, 2>>& xy) {
    points_to_xy(pts, xy);
    to_ccw(xy);
}

inline void xy_to_points(const std::vector<std::array<double, 2>>& xy,
                         std::vector<Point>& out) {
    out.clear();
    if (xy.size() < 3) return;
    out.reserve(xy.size());
    for (const auto& p : xy) out.emplace_back(p[0], p[1]);
}

// Clip convex subject P by convex clip Q; both given as Epick points.  Returns
// a const reference to the thread-local intersection polygon (CCW, no closing
// duplicate) in Epick points, or an empty vector when the intersection is
// degenerate (<3 vertices).  The returned reference is valid until the next
// clip() call on the same thread.
inline const std::vector<Point>& clip(const std::vector<Point>& P_verts,
                                      const std::vector<Point>& Q_verts) {
    ClipWorkspace& ws = get_clip_workspace();

    const int n = static_cast<int>(P_verts.size());
    const int m = static_cast<int>(Q_verts.size());
    if (n < 3 || m < 3) { ws.result.clear(); return ws.result; }

    points_to_xy(P_verts, ws.subj);
    points_to_xy(Q_verts, ws.clipv);
    to_ccw(ws.subj);
    to_ccw(ws.clipv);
    clip_convex_ccw(ws.subj, ws.clipv, ws.out, ws.in);
    xy_to_points(ws.out, ws.result);
    return ws.result;
}

// Same clip as clip(), but Q is already CCW doubles (prepared conv(G_i)).
inline const std::vector<Point>& clip_against_xy(
    const std::vector<Point>& P_verts,
    const std::vector<std::array<double, 2>>& clip_xy) {
    ClipWorkspace& ws = get_clip_workspace();
    if (P_verts.size() < 3 || clip_xy.size() < 3) {
        ws.result.clear();
        return ws.result;
    }
    points_to_xy(P_verts, ws.subj);
    to_ccw(ws.subj);
    clip_convex_ccw(ws.subj, clip_xy, ws.out, ws.in);
    xy_to_points(ws.out, ws.result);
    return ws.result;
}

